/* Pvars of a moby that circles a centre point, keeping to the side away from the hero. */
typedef struct {
    u8 pad0[0xB0];
    struct Moby *focus;   /* 0xB0: moby it keeps facing */
    u8 padB4[0x1C];
    Vec3 center;          /* 0xD0 */
    f32 radius;           /* 0xDC */
    f32 yaw_vel;          /* 0xE0 */
    u8 padE4[4];
    f32 speed;            /* 0xE8 */
    s32 ground;           /* 0xEC */
} CirclerVars;

